-- =====================================================================
-- 02_seed.sql  |  Carga do CRM (Atlas Software) - workshop Databricks + IA
-- Datas relativas a now(): rode de novo e o dado volta 'fresco'.
-- Idempotente: limpa e recarrega tudo (use para resetar entre ensaios).
-- =====================================================================
BEGIN;
TRUNCATE crm.interacoes, crm.oportunidades, crm.leads, crm.produtos, crm.vendedores RESTART IDENTITY CASCADE;






-- realinha as sequences após inserts com id explícito
DO $$ BEGIN
  PERFORM setval(pg_get_serial_sequence('crm.vendedores','id'), (SELECT max(id) FROM crm.vendedores));
  PERFORM setval(pg_get_serial_sequence('crm.produtos','id'), (SELECT max(id) FROM crm.produtos));
  PERFORM setval(pg_get_serial_sequence('crm.leads','id'), (SELECT max(id) FROM crm.leads));
  PERFORM setval(pg_get_serial_sequence('crm.oportunidades','id'), (SELECT max(id) FROM crm.oportunidades));
  PERFORM setval(pg_get_serial_sequence('crm.interacoes','id'), (SELECT max(id) FROM crm.interacoes));
END $$;
-- atualizado_em coerente com a criação (o trigger marcaria tudo como 'agora')
ALTER TABLE crm.leads DISABLE TRIGGER trg_leads_atualizado_em;
UPDATE crm.leads SET atualizado_em = criado_em + interval '2 days' * random();
UPDATE crm.leads SET atualizado_em = now() WHERE atualizado_em > now();
ALTER TABLE crm.leads ENABLE TRIGGER trg_leads_atualizado_em;
COMMIT;
